Query:
EVALUATE
SUMMARIZECOLUMNS(
    'Period'[Week 445],
    "Net Sales Revenue",
        CALCULATE(
            [Bottler Net Revenue AC (LC)],
            KEEPFILTERS('Ship From'[Country] = "Colombia"),
            KEEPFILTERS(
                'Period'[Week 445] IN {
                    "2026 W02",
                    "2026 W03",
                    "2026 W04"
                }
            )
        ),
    "Net Sales Revenue % vs PY",
        CALCULATE(
            [Bottler Net Revenue AC % vs PY (LC)],
            KEEPFILTERS('Ship From'[Country] = "Colombia"),
            KEEPFILTERS(
                'Period'[Week 445] IN {
                    "2026 W02",
                    "2026 W03",
                    "2026 W04"
                }
            )
        )
)
ORDER BY 'Period'[Week 445] ASC

EVALUATE
SUMMARIZECOLUMNS(
    'Channel'[LT1.3 - Channel Macro Group],
    "Net Sales Revenue",
        CALCULATE(
            [Bottler Net Revenue AC (LC)],
            KEEPFILTERS(
                'Channel'[LT1.3 - Channel Macro Group] IN {
                    "Modern Trade",
                    "Traditional Trade"
                }
            ),
            KEEPFILTERS('Ship From'[Country] = "Colombia"),
            KEEPFILTERS('Period'[Month 445] = "2025 Dec")
        ),
    "Net Sales Revenue YoY %",
        CALCULATE(
            [Bottler Net Revenue AC (LC) % vs PY],
            KEEPFILTERS(
                'Channel'[LT1.3 - Channel Macro Group] IN {
                    "Modern Trade",
                    "Traditional Trade"
                }
            ),
            KEEPFILTERS('Ship From'[Country] = "Colombia"),
            KEEPFILTERS('Period'[Month 445] = "2025 Dec")
        ),
    "Unit Cases",
        CALCULATE(
            [Unit Cases AC],
            KEEPFILTERS(
                'Channel'[LT1.3 - Channel Macro Group] IN {
                    "Modern Trade",
                    "Traditional Trade"
                }
            ),
            KEEPFILTERS('Ship From'[Country] = "Colombia"),
            KEEPFILTERS('Period'[Month 445] = "2025 Dec")
        ),
    "Unit Cases YoY %",
        CALCULATE(
            [Unit Cases AC % vs PY],
            KEEPFILTERS(
                'Channel'[LT1.3 - Channel Macro Group] IN {
                    "Modern Trade",
                    "Traditional Trade"
                }
            ),
            KEEPFILTERS('Ship From'[Country] = "Colombia"),
            KEEPFILTERS('Period'[Month 445] = "2025 Dec")
        )
)
ORDER BY [Net Sales Revenue YoY %] DESC
